def transform(H,W,wall,sources):
    cells={(wall,c):2 for c in range(W)}
    for r,c in sources:
        toward=1 if r<wall else -1
        landing=(r+toward,c)
        cells[landing]=4
        if abs(r-wall)==2:
            rr,cc=landing
            away=-toward
            for dc in (-1,1):
                x,y=rr+away,cc+dc
                while 0<=x<H and 0<=y<W:
                    cells[(x,y)]=4
                    x+=away; y+=dc
    grid=[[cells.get((r,c),0) for c in range(W)] for r in range(H)]
    return grid
for name,H,W,wall,src in [('demo1',7,5,6,[(4,2)]),('demo2',10,6,5,[(2,1),(3,4)]),('test',12,8,3,[(0,4),(1,0),(6,1)])]:
    g=transform(H,W,wall,src)
    print(name)
    print('\n'.join(' '.join(map(str,row)) for row in g))

